const n = $input.first().json;
let message = '';

switch(n.event_type) {
  case 'ENTRY_CREATED':
    message = `🟢 *BUY SIGNAL*\n📌 Symbol: *${n.symbol}*\n💰 Entry: ₹${parseFloat(n.entry_price).toFixed(2)}\n🛑 SL: ₹${parseFloat(n.sl).toFixed(2)}\n🎯 Target: ₹${parseFloat(n.current_target).toFixed(2)}\n📊 Scanner: ${n.scan_name}`;
    break;
  case 'TARGET_HIT':
    message = `🎯 *TARGET HIT*\n📌 ${n.symbol}\n✅ Profit: +${parseFloat(n.pnl_pct).toFixed(2)}%\n💰 P&L: +₹${parseFloat(n.pnl).toFixed(2)}\n🔄 Trailing mode activated`;
    break;
  case 'STOP_LOSS_HIT':
    message = `🔴 *STOP LOSS HIT*\n📌 ${n.symbol}\n📉 Loss: ${parseFloat(n.pnl_pct).toFixed(2)}%\n💸 P&L: ₹${parseFloat(n.pnl).toFixed(2)}\n🏁 Exit: ₹${parseFloat(n.exit_price || 0).toFixed(2)}`;
    break;
  case 'TRAILING':
    message = `📈 *TRAILING PROFIT LOCKED*\n📌 ${n.symbol}\n🔒 Gain locked: +${parseFloat(n.pnl_pct).toFixed(2)}%`;
    break;
  default:
    message = `📊 Trade Update: ${n.symbol} — ${n.event_type}`;
}

return [{ json: { ...n, formatted_message: message } }];
